struct Config {
    host: String,
    port: u16,
    verbose: bool,
}

struct ConfigBuilder {
    host: String,
    port: u16,
    verbose: bool,
}

impl ConfigBuilder {
    fn new() -> Self {
        ConfigBuilder { host: "".into(), port: 8080, verbose: false }
    }
    fn host(mut self, host: String) -> Self {
        self.host = host;
        self
    }
    fn port(mut self, port: u16) -> Self {
        self.port = port;
        self
    }
    fn verbose(mut self, verbose: bool) -> Self {
        self.verbose = verbose;
        self
    }
    fn build(self) -> Config {
        Config { host: self.host, port: self.port, verbose: self.verbose }
    }
}

